"""Build the 100-strain guide and source-attributed ancestry exports."""
import csv
import json
from strain_ancestry import DATA, ROOT, analyze
OUT = ROOT / 'ancestry.html'

def main():
    data = json.loads(DATA.read_text())
    report = analyze(data)
    if report['errors']:
        raise ValueError(report['errors'])
    payload = json.dumps({'data': data, 'report': report}, ensure_ascii=False).replace('<', '\\u003c')
    page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>100 popular cannabis strains</title>
<style>:root{--red:#a90000;--ink:#252525;--line:#d7d7d3}*{box-sizing:border-box}body{font:16px/1.55 system-ui;background:#f5f5f3;color:var(--ink);margin:0}main{max-width:1120px;margin:auto;padding:24px}a{color:var(--red)}h1{font-size:clamp(2rem,5vw,3.2rem);line-height:1.1;margin-bottom:14px}h2{margin:0 0 8px;font-size:1.45rem}h3{font-size:1rem;margin:18px 0 5px}.lead{max-width:760px;font-size:1.1rem}.notice,article{background:white;border:1px solid var(--line);border-radius:10px;padding:22px}.notice{margin:22px 0}.notice p{margin:8px 0}input,select,button{font:inherit;padding:10px;max-width:100%;border:1px solid #999;border-radius:5px}input{width:100%}.filters{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0}.filters label{font-size:.9rem}.filters select{display:block;width:100%;margin-top:4px}#results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}article{min-width:0;overflow-wrap:anywhere}.muted{color:#555}.tag{font-size:.8rem;color:#555;text-transform:uppercase;letter-spacing:.04em}.tags{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.chip{border:1px solid var(--line);border-radius:30px;padding:3px 9px;font-size:.85rem}.review{color:#7a4200;font-size:.9rem}.parents{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.node{border:1px solid var(--line);border-radius:8px;padding:10px;min-width:0}.node p{font-size:.85rem}details{margin-top:16px;border-top:1px solid var(--line);padding-top:12px}summary{cursor:pointer;color:var(--red);font-weight:600}.pager{display:flex;align-items:center;gap:14px;margin:24px 0;flex-wrap:wrap}button{cursor:pointer;background:white;color:var(--red)}button:disabled{color:#777;cursor:default}a:focus-visible,input:focus-visible,select:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #3367b1;outline-offset:3px}.source{font-size:.85rem}.identity{margin:12px 0}#count{font-weight:600}@media(max-width:650px){main{padding:16px}#results{grid-template-columns:1fr}.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.parents{grid-template-columns:1fr}}@media print{input,.filters,.pager,summary{display:none}#results{display:block}article{break-inside:avoid;margin-bottom:12px}}</style></head>
<body><main><a href="index.html">← Ohio Cannabis Directory</a><p><a href="knowledge.html">Cannabis knowledge: forms, definitions and labels</a></p><p class="tag">Strain library · reviewed October 10, 2026</p><h1>100 popular cannabis strains</h1><p class="lead">Explore familiar classics and modern favorites. Discover their reported genetics, stories, flavors and effects.</p>
<div class="notice"><strong>A curated guide, with sources</strong><p>These 100 names combine widely recognized classics, modern favorites and CBD-associated cultivars. This is an unranked selection, not a verified national top-100 sales chart or Ohio stock list. <a href="data/strains/README.md">Selection and research notes</a>.</p><p>Effects and sensory tags are reader reports, not promises. Chemistry varies by batch. Check the actual product label for THC, CBD and terpenes. <a href="knowledge.html#labels">Learn to read a label</a>.</p><a href="data/strains/strains.csv" download>Download all 100 profiles (CSV)</a> · <a href="data/strains/ancestry.csv" download>Ancestry claims (CSV)</a> · <a href="data/strains/ancestry.json" download>Source records (JSON)</a></div>
<label for="q">Search strain, alias, parent or history</label><input id="q" type="search" placeholder="Try Blue Dream, Cookies or DJ Short" autocomplete="off">
<div class="filters"><label>View<select id="mode"><option value="popular">100 popular strains</option><option value="review">Ancestry needs review</option><option value="lines">Breeder-line examples</option></select></label><label>Type<select id="type"><option value="">All types</option><option>hybrid</option><option>indica</option><option>sativa</option></select></label><label>Reported effect<select id="effect"><option value="">All effects</option></select></label><label>Reported flavor<select id="flavor"><option value="">All flavors</option></select></label><label>Sort<select id="sort"><option value="name">Name A–Z</option><option value="reviews">Most reviewed within this list</option></select></label></div>
<p id="count" aria-live="polite"></p><div id="results"></div><nav class="pager" aria-label="Strain pages"><button id="prev">Previous</button><span id="page" aria-live="polite"></span><button id="next">Next</button></nav><details><summary>Breeder identity decisions</summary><div id="decisions"></div></details><noscript>This searchable guide needs JavaScript. Download the CSV above to browse all 100 profiles.</noscript></main><script id="model" type="application/json">__DATA__</script>
<script>
const {data,report}=JSON.parse(document.getElementById('model').textContent),byId=Object.fromEntries(data.strains.map(s=>[s.id,s])),sources=Object.fromEntries(data.sources.map(s=>[s.id,s]));
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=s=>escape(s.name)+' · '+escape(s.breeder||'cut identity unresolved'),needs=new Set([...report.parentage_review.map(r=>r.child_id),...data.strains.filter(s=>s.ancestry_status==='needs-review').map(s=>s.id)]);
let page=1;const pageSize=20;let selectedId=new URLSearchParams(location.search).get('strain');
function sourceLinks(ids){return (ids||[]).map(id=>'<a href="'+escape(sources[id].url)+'" target="_blank" rel="noopener">'+escape(sources[id].publisher)+'</a> · checked '+escape(sources[id].reviewed_on)).join(' / ');}
function tree(id,seen=new Set(),depth=0){if(seen.has(id)||depth>=4)return '<p class="muted">Further ancestry not expanded.</p>';let next=new Set(seen);next.add(id);const claims=data.claims.filter(c=>c.child_id===id&&c.status!=='superseded');if(!claims.length)return '<p class="muted">No two-parent claim modeled. See the reported lineage above; a selection, complex cross or unknown ancestry is not forced into a two-parent tree.</p>';return claims.map(c=>'<section><p class="tag">'+escape(c.status)+' · parent direction unspecified</p><div class="parents">'+c.parent_ids.map(p=>'<div class="node"><strong>'+label(byId[p])+'</strong><p class="muted">Unresolved parent reference; not a verified connection to every same-name strain.</p>'+(data.claims.some(c=>c.child_id===p)?tree(p,next,depth+1):'')+'</div>').join('')+'</div><p class="source">'+escape(c.notes)+'</p><p class="source">'+sourceLinks(c.source_ids)+'</p></section>').join('');}
const chips=items=>'<div class="tags">'+(items||[]).map(x=>'<span class="chip">'+escape(x)+'</span>').join('')+'</div>';
function card(s){return '<article id="'+escape(s.id)+'"><p class="tag">'+escape(s.category||s.kind)+(s.review_count?' · '+s.review_count.toLocaleString()+' reader reports':'')+'</p><h2><a href="?strain='+encodeURIComponent(s.id)+'">'+escape(s.name)+'</a></h2>'+(s.aliases.length?'<p class="source">Also indexed as '+s.aliases.map(escape).join(', ')+'</p>':'')+'<p>'+escape(s.lineage_text||s.breeder||'Breeder-line example')+'</p>'+(needs.has(s.id)?'<p class="review">Ancestry needs review — '+escape(s.review_note||'Source specificity differs.')+'</p>':'')+(s.popular?'<h3>Reported effects</h3>'+chips(s.reported_effects)+'<h3>Reported flavors</h3>'+chips(s.reported_flavors):'')+'<details class="profile-details"><summary>History, genetics and sources</summary>'+(s.history?'<h3>Background</h3><p>'+escape(s.history)+'</p>':'')+(s.reported_terpenes?.length?'<h3><a href="knowledge.html#terpenes">Terpenes</a> listed by source</h3>'+chips(s.reported_terpenes)+'<p class="source muted">Profile-level reports; verify the current batch.</p>':'')+'<h3>Ancestry</h3>'+tree(s.id)+(s.review_note?'<p class="source">'+escape(s.review_note)+'</p>':'')+'<p class="source">'+sourceLinks(s.profile_source_ids)+'</p></details></article>';}
function render(){const q=$('q').value.toLowerCase(),mode=$('mode').value;const matches=data.strains.filter(s=>{if(selectedId&&s.id!==selectedId)return false;if(mode==='lines'?!['seed-line','clone'].includes(s.kind):!s.popular)return false;const text=[s.name,s.breeder,...s.aliases,s.lineage_text,s.history].join(' ').toLowerCase();return text.includes(q)&&(mode!=='review'||needs.has(s.id))&&(!$('type').value||s.category===$('type').value)&&(!$('effect').value||s.reported_effects?.includes($('effect').value))&&(!$('flavor').value||s.reported_flavors?.includes($('flavor').value));});matches.sort($('sort').value==='reviews'?(a,b)=>(b.review_count||0)-(a.review_count||0)||a.name.localeCompare(b.name):(a,b)=>a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(matches.length/pageSize));page=Math.min(page,pages);$('count').textContent=matches.length+' matching '+(mode==='lines'?'breeder-line records':'strains')+(mode==='popular'?' from 100 profiles':'');$('results').innerHTML=matches.slice((page-1)*pageSize,page*pageSize).map(card).join('')||'<p>No matching strains. Try clearing a filter.</p>';$('page').textContent='Page '+page+' of '+pages;$('prev').disabled=page===1;$('next').disabled=page===pages;}
for(const [id,field] of [['effect','reported_effects'],['flavor','reported_flavors']]){const values=[...new Set(data.strains.flatMap(s=>s[field]||[]))].sort();$(id).innerHTML+=values.map(x=>'<option>'+escape(x)+'</option>').join('');}
$('decisions').innerHTML=data.resolutions.map(r=>'<div class="identity"><strong>'+escape(r.decision)+'</strong><p>'+r.strain_ids.map(id=>label(byId[id])).join('<br>')+'</p><p>'+escape(r.reason)+'</p></div>').join('');for(const id of ['q','mode','type','effect','flavor','sort'])$(id).addEventListener(id==='q'?'input':'change',()=>{selectedId=null;history.replaceState(null,'',location.pathname);page=1;render();});for(const [id,delta] of [['prev',-1],['next',1]])$(id).addEventListener('click',()=>{page+=delta;render();$('count').scrollIntoView({block:'start'});});
const selected=byId[new URLSearchParams(location.search).get('strain')];if(selected){$('q').value=selected.name;if(!selected.popular)$('mode').value='lines';}render();
</script></body></html>'''.replace('__DATA__',payload)
    OUT.write_text(page)
    strains={s['id']:s for s in data['strains']};sources={s['id']:s for s in data['sources']}
    with (ROOT/'data/strains/ancestry.csv').open('w',newline='') as f:
        writer=csv.writer(f,lineterminator='\n');writer.writerow(['claim_id','child_id','strain','breeder','parent_1_id','parent_1_name','parent_2_id','parent_2_name','status','source_urls','reviewed_on','notes'])
        for c in data['claims']:
            child=strains[c['child_id']];a,b=c['parent_ids'];writer.writerow([c['id'],child['id'],child['name'],child['breeder'],a,strains[a]['name'],b,strains[b]['name'],c['status'],' | '.join(sources[s]['url'] for s in c['source_ids']),data['reviewed_on'],c['notes']])
    with (ROOT/'data/strains/strains.csv').open('w',newline='') as f:
        writer=csv.writer(f,lineterminator='\n');writer.writerow(['id','strain','aliases','type','reported_genetics','history','reported_effects','reported_flavors','source_terpenes','reader_report_count','ancestry_status','review_note','source_urls','reviewed_on'])
        for s in sorted((s for s in data['strains'] if s.get('popular')),key=lambda s:s['name'].casefold()):
            writer.writerow([s['id'],s['name'],' | '.join(s['aliases']),s['category'],s['lineage_text'],s['history'],' | '.join(s['reported_effects']),' | '.join(s['reported_flavors']),' | '.join(s['reported_terpenes']),s['review_count'],s['ancestry_status'],s['review_note'],' | '.join(sources[id]['url'] for id in s['profile_source_ids']),s['reviewed_on']])
    print('Built ancestry.html, ancestry.csv and strains.csv (100 profiles)')
if __name__=='__main__':main()
